//! A small infer bridge for TensorRT.
//!
//! The safe Rust API lives here; the raw FFI bindings are generated by
//! `build.rs` when the `ffi` feature is enabled, and the C++ bridge DLL is
//! loaded at runtime through `dll::Bridge` (never linked at build time).

pub mod engine;
pub mod error;

pub use engine::Engine;
pub use error::{InferError, InferResult};

/// Generate raw C bindings (only compiled with the `ffi` feature).
///
/// bindgen also emits the `extern "C"` declarations and some C library typedefs;
/// both are unused here (`dll::Bridge` resolves symbols dynamically), so their
/// naming and dead-code warnings are suppressed.
#[cfg(feature = "ffi")]
pub mod ffi;

/// Runtime loading of the bridge DLL (only with the `ffi` feature).
#[cfg(feature = "ffi")]
pub mod dll;

#[cfg(feature = "ffi")]
pub use dll::Bridge;
